import org.junit.jupiter.api.parallel.Resources;

/** Public query/telemetry coverage for physical interpreted predicate calls. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbNativeScalarFilterTelemetryTest {
	private static final String EX = "urn:rdf4j:test:scalar-filter-telemetry:";
	private static final String FUNCTION = EX + "even";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String SCALAR_METRIC = "nativeScalarFilterInvocationsActual";
	private static final String IR_METRIC = "nativeIrValueFilterEvaluationsActual";

	@TempDir
	File dataDir;

	private final CountingEvenFunction function = new CountingEvenFunction();
	private Function previousFunction;
	private String previousNative;
	private SailRepository repository;

	@BeforeEach
	void setUp() {
		previousNative = System.getProperty(NATIVE_FLAG);
		System.setProperty(NATIVE_FLAG, "true");
		FunctionRegistry registry = FunctionRegistry.getInstance();
		previousFunction = registry.get(FUNCTION).orElse(null);
		registry.add(function);
		repository = new SailRepository(new LmdbStore(dataDir,
				new LmdbStoreConfig("spoc,posc").setNativeEvaluationEnabled(true)));
		repository.init();
		ValueFactory vf = repository.getValueFactory();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			for (int i = 1; i <= 7; i++) {
				connection.add(vf.createIRI(EX, "subject/" + i), vf.createIRI(EX, "number"),
						vf.createLiteral(i));
				connection.add(vf.createIRI(EX, "early/" + i), vf.createIRI(EX, "early-number"),
						vf.createLiteral(2));
			}
			connection.commit();
		}
	}

	@AfterEach
	void tearDown() {
		try {
			if (repository != null) {
				repository.shutDown();
			}
		} finally {
			FunctionRegistry registry = FunctionRegistry.getInstance();
			registry.remove(function);
			if (previousFunction != null) {
				registry.add(previousFunction);
			}
			if (previousNative == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previousNative);
			}
		}
	}

	@Test
	void completedScalarFilterReportsExactlySevenPredicateCalls() {
		String query = query("number", "");
		function.calls.set(0);
		assertThat(rows(query)).containsExactly(2, 4, 6);
		assertThat(function.calls.get()).as("one independent predicate call per source row").isEqualTo(7);

		// explain(Telemetry) performs a separate execution; reset the oracle for that exact execution.
		function.calls.set(0);
		GenericPlanNode plan = telemetry(query);
		int observedCalls = function.calls.get();
		assertAll("completed interpreted filter work",
				() -> assertThat(observedCalls).as("the telemetry execution also evaluates all seven rows")
						.isEqualTo(7),
				() -> assertThat(metric(plan, SCALAR_METRIC)).as("actual scalar accept calls are reported")
						.isNotNull()
						.isEqualTo(observedCalls),
				() -> assertThat(metric(plan, IR_METRIC)).as("the scalar route reports no IR filter metric").isNull(),
				() -> assertThat(plan.toString()).as("the public explanation must execute a native row route")
						.contains("nativeExecutionPath="));
	}

	@Test
	void acceptedSliceReportsTheCallsActuallyMadeBeforeItsProducerCloses() {
		String query = query("early-number", " LIMIT 1");
		assertThat(rows(query)).containsExactly(2);

		function.calls.set(0);
		GenericPlanNode plan = telemetry(query);
		int observedCalls = function.calls.get();
		assertAll("accepted slice owns its actual scalar work",
				() -> assertThat(observedCalls).as("the slice evaluates a positive prefix, without reopening effects")
						.isBetween(1, 7),
				() -> assertThat(metric(plan, SCALAR_METRIC)).as("close publishes exactly the independent call count")
						.isNotNull()
						.isEqualTo(observedCalls),
				() -> assertThat(metric(plan, IR_METRIC)).as("the scalar slice reports no IR filter metric").isNull());
	}

	private String query(String predicate, String suffix) {
		return "SELECT ?value WHERE { ?subject <" + EX + predicate + "> ?value . FILTER(<" + FUNCTION
				+ ">(?value)) }" + suffix;
	}

	private List<Integer> rows(String text) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(text);
			query.setLmdbResultCacheRequested(false);
			try (TupleQueryResult result = query.evaluate()) {
				return QueryResults.asList(result)
						.stream()
						.map(row -> ((Literal) row.getValue("value")).intValue())
						.sorted()
						.toList();
			}
		}
	}

	private GenericPlanNode telemetry(String text) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(text);
			query.setLmdbResultCacheRequested(false);
			return query.explain(Explanation.Level.Telemetry).toGenericPlanNode();
		}
	}

	private static Long metric(GenericPlanNode node, String name) {
		Long own = node.getLongMetricActual(name);
		boolean reported = own != null && own >= 0L;
		long total = reported ? own : 0L;
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				Long childTotal = metric(child, name);
				if (childTotal != null) {
					total += childTotal;
					reported = true;
				}
			}
		}
		return reported ? total : null;
	}

	private static final class CountingEvenFunction implements Function {
		private final AtomicInteger calls = new AtomicInteger();

		@Override
		public String getURI() {
			return FUNCTION;
		}

		@Override
		@SuppressWarnings("deprecation")
		public Value evaluate(ValueFactory valueFactory, Value... args) {
			calls.incrementAndGet();
			return valueFactory.createLiteral(((Literal) args[0]).intValue() % 2 == 0);
		}

		@Override
		public Determinism getDeterminism() {
			// The independent invocation oracle is an effect: speculative replay and constant folding are illegal.
			return Determinism.VOLATILE;
		}
	}
}
